package com.andye.warmod.antiair;import com.andye.warmod.WarMod;import com.andye.warmod.antiair.network.*;import com.andye.warmod.radar.*;import com.andye.warmod.silo.*;import com.andye.warmod.warhead.*;import java.util.*;import net.minecraft.SharedConstants;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.phys.Vec3;import org.jspecify.annotations.Nullable;
public final class AntiAirFlightController{private final AntiAirFlightPlan plan;private final @Nullable MissileSiloCollisionContext collisionContext;private final AntiAirChunkTicketController tickets=new AntiAirChunkTicketController();private AntiAirFlightPhase phase=AntiAirFlightPhase.IGNITION;private Vec3 previousPosition,currentPosition,currentVelocity=Vec3.ZERO;private @Nullable Vec3 previousTarget;private @Nullable AntiAirRoute route;private long routeLockTime,selfDestructStart,fallbackStart;private boolean completed;AntiAirFlightController(AntiAirFlightPlan p,@Nullable MissileSiloCollisionContext c){plan=p;collisionContext=c;previousPosition=currentPosition=p.launchPosition();}public AntiAirFlightPlan plan(){return plan;}public boolean completed(){return completed;}
public void tick(ServerLevel l){if(completed)return;long now=l.getGameTime(),elapsed=Math.max(0,now-plan.launchGameTime());previousPosition=currentPosition;if(phase==AntiAirFlightPhase.IGNITION||phase==AntiAirFlightPhase.BOOST){phase=elapsed<plan.ignitionTicks()?AntiAirFlightPhase.IGNITION:AntiAirFlightPhase.BOOST;currentPosition=AntiAirTrajectory.boostPosition(plan,elapsed);currentVelocity=AntiAirTrajectory.boostVelocity(plan,elapsed);if(collisionContext!=null){var hit=MissileSiloCollisionDetector.findFirst(l,previousPosition,currentPosition,collisionContext);if(hit!=null){detonate(l,hit.impactPosition(),WarheadEffectProfile.ANTI_AIR_LAUNCH_FAILURE);return;}}if(elapsed>=plan.ignitionTicks()+plan.boostTicks()){if(plan.debugNoTargetFlight()){beginSelfDestruct(l);return;}if(plan.targetLock()==null||StrategicMissileTargetService.state(l,plan.targetRootTrackId(),now).isEmpty()){targetLost(l);return;}lockRoute(l);}}else if(phase==AntiAirFlightPhase.INTERCEPT)tickIntercept(l,now);else if(phase==AntiAirFlightPhase.FALLBACK)tickFallback(l,now);else if(phase==AntiAirFlightPhase.SELF_DESTRUCT&&now-selfDestructStart>=AntiAirConstants.MK_II_SELF_DESTRUCT_DELAY_TICKS)detonate(l,currentPosition,WarheadEffectProfile.ANTI_AIR_SAFE_SELF_DESTRUCT);}
private void lockRoute(ServerLevel l){var nominal=plan.nominalSolution();if(nominal==null){targetLost(l);return;}Vec3 tangent=nominal.nominalRoute().controlPoint1().subtract(nominal.nominalRoute().start());var resolution=AntiAirGuidanceResolver.resolve(new AntiAirGuidanceProfile(plan.interceptorId(),plan.sourceSiloId()==null?plan.interceptorId():plan.sourceSiloId(),plan.capturedGuidanceTier(),nominal.perfectInterceptPosition(),nominal.targetVelocityAtIntercept(),plan.visualSeed()^0x47554944414E4345L),tangent);AntiAirRoute n=nominal.nominalRoute();route=new AntiAirRoute(plan.burnoutPosition(),n.controlPoint1(),n.controlPoint2().add(resolution.offset()),resolution.resolvedInterceptPosition(),n.durationTicks());routeLockTime=l.getGameTime();phase=AntiAirFlightPhase.INTERCEPT;RadarInterceptorRouteSnapshot rr=new RadarInterceptorRouteSnapshot(route.controlPoint1(),route.controlPoint2(),route.end(),route.durationTicks(),routeLockTime,resolution.missDistance());RadarTrackingService.updateInterceptorRoute(l,plan.interceptorId(),rr);AntiAirNetworking.send(l,new ClientboundAntiAirRouteLockPayload(plan.interceptorId(),plan.targetRootTrackId(),route.controlPoint1(),route.controlPoint2(),route.end(),route.durationTicks(),resolution.missDistance(),routeLockTime));AntiAirNetworking.send(l,new ClientboundAntiAirPhasePayload(plan.interceptorId(),phase,routeLockTime));}
private void tickIntercept(ServerLevel l,long now){var target=StrategicMissileTargetService.state(l,plan.targetRootTrackId(),now);if(target.isEmpty()||!target.get().active()){targetLost(l);return;}double age=now-routeLockTime;currentPosition=route.position(age);currentVelocity=route.velocity(age);Vec3 targetPos=target.get().currentPosition();if(previousTarget==null)previousTarget=targetPos.subtract(target.get().currentVelocity());Closest closest=closest(previousPosition,currentPosition,previousTarget,targetPos);previousTarget=targetPos;if(closest.distanceSquared<=AntiAirConstants.INTERCEPT_FUSE_RADIUS_SQUARED){var result=StrategicMissileInterceptionService.intercept(l,plan.targetRootTrackId(),plan.interceptorId(),closest.midpoint);if(result.success()){WarheadImpactService.detonateAntiAir(l,plan.interceptorId(),closest.midpoint,plan.visualSeed(),WarheadEffectProfile.ANTI_AIR_INTERCEPTION);RadarTrackingService.registerInterception(l,new RadarInterceptionSnapshot(plan.interceptorId(),plan.targetRootTrackId(),closest.midpoint,l.getGameTime(),plan.variant(),result.payloadType().orElseThrow()));complete(l,RadarRemovalReason.INTERCEPTED);return;}targetLost(l);return;}if(age>=route.durationTicks()){if(plan.variant().ballisticFallback())beginFallback(l);else beginSelfDestruct(l);}}
private void targetLost(ServerLevel l){if(plan.debugNoTargetFlight()||!plan.variant().ballisticFallback())beginSelfDestruct(l);else if(route==null&&l.getGameTime()-plan.launchGameTime()<plan.ignitionTicks()+plan.boostTicks())return;else beginFallback(l);}
private void beginFallback(ServerLevel l){phase=AntiAirFlightPhase.FALLBACK;fallbackStart=l.getGameTime();if(currentVelocity.lengthSqr()<1e-8)currentVelocity=new Vec3(0,-.1,0);RadarTrackingService.updateInterceptorPhase(l,plan.interceptorId(),RadarTrackPhase.FALLBACK);AntiAirNetworking.send(l,new ClientboundAntiAirPhasePayload(plan.interceptorId(),phase,fallbackStart));}
private void tickFallback(ServerLevel l,long now){tickets.updateFallback(l,currentPosition);currentVelocity=AntiAirFallbackTrajectory.nextVelocity(currentVelocity);Vec3 next=AntiAirFallbackTrajectory.nextPosition(currentPosition,currentVelocity);MissileSiloCollisionContext context=new MissileSiloCollisionContext(plan.sourceSiloId()==null?plan.interceptorId():plan.sourceSiloId(),plan.sourceSiloCentre()==null?net.minecraft.core.BlockPos.containing(currentPosition):plan.sourceSiloCentre(),Set.of(),.35,2.2);var hit=MissileSiloCollisionDetector.findFirst(l,currentPosition,next,context);currentPosition=next;if(hit!=null||now-fallbackStart>=AntiAirConstants.MAXIMUM_FALLBACK_LIFETIME_TICKS){detonate(l,hit==null?currentPosition:hit.impactPosition(),WarheadEffectProfile.ANTI_AIR_FALLBACK);}}
private void beginSelfDestruct(ServerLevel l){phase=AntiAirFlightPhase.SELF_DESTRUCT;selfDestructStart=l.getGameTime();RadarTrackingService.updateInterceptorPhase(l,plan.interceptorId(),RadarTrackPhase.SELF_DESTRUCT);AntiAirNetworking.send(l,new ClientboundAntiAirPhasePayload(plan.interceptorId(),phase,selfDestructStart));}
private void detonate(ServerLevel l,Vec3 p,WarheadEffectProfile effect){WarheadImpactService.detonateAntiAir(l,plan.interceptorId(),p,plan.visualSeed(),effect);complete(l,RadarRemovalReason.CANCELLED);}private void complete(ServerLevel l,RadarRemovalReason reason){tickets.releaseAll(l);RadarTrackingService.removeInterceptor(l,plan.interceptorId(),reason);AntiAirNetworking.send(l,new ClientboundAntiAirRemovePayload(plan.interceptorId()));completed=true;phase=AntiAirFlightPhase.COMPLETED;}
private static Closest closest(Vec3 a0,Vec3 a1,Vec3 b0,Vec3 b1){Vec3 r0=a0.subtract(b0),rv=a1.subtract(a0).subtract(b1.subtract(b0));double d=rv.lengthSqr(),t=d<1e-12?0:Math.max(0,Math.min(1,-r0.dot(rv)/d));Vec3 a=a0.lerp(a1,t),b=b0.lerp(b1,t);return new Closest(a.distanceToSqr(b),a.add(b).scale(.5));}private record Closest(double distanceSquared,Vec3 midpoint){} }